schedule-page.source:
/**
 * /programme — both conference days, in full.
 *
 *   thursday   day one, three tracks
 *   friday     day two, three tracks
 *   answers    how to read a grid with three things in every slot
 *
 * TWO <EventAgendaGrid>s, NOT ONE WITH A DAY SWITCHER. A tab control would
 * be the obvious interactive choice and it is the wrong one here for three
 * reasons: the page is the artefact people print and pin to a wall, a tab
 * hides half of it from find-in-page, and a delegate comparing "am I free
 * on Friday afternoon" wants both days in one scroll. Two grids also means
 * the page works with JavaScript off, which matters at a conference where
 * everyone is on the same overloaded wifi.
 *
 * Each grid gets a distinct `heading` and `dayLabel`, which is load-bearing
 * rather than cosmetic: <EventAgendaGrid> derives its `aria-labelledby`
 * target by hashing those two strings, so two grids with identical headings
 * would emit the same id twice and the second day would be announced with
 * the first day's heading. This is the duplicate-id trap that the catalog
 * hits whenever a block appears twice, solved from the caller's side
 * because the caller is the only one who knows they differ.
 *
 * NO NAVBAR CTA TO "BOOK". The person reading a full programme has either
 * already bought a ticket or is deciding on content, and both are better
 * served by the schedule being uninterrupted. The ticket link is in the nav
 * like any other route.
 */

import * as React from 'react'
import { NavbarSimple } from '@/components/navbar-simple'
import { EventAgendaGrid } from '@/components/event-agenda-grid'
import { FaqAccordion } from '@/components/faq-accordion'
import { FooterMinimal } from '@/components/footer-minimal'

const THURSDAY = [
  {
    start: '08:30',
    end: '09:30',
    sessions: [{ title: 'Registration and coffee', kind: 'break' as const, room: 'Foyer' }],
  },
  {
    start: '09:30',
    end: '10:15',
    sessions: [
      {
        title: 'What we got wrong about build tooling, twice',
        speaker: 'Aisling Moreau',
        room: 'Great Hall',
        kind: 'keynote' as const,
        href: '#',
      },
    ],
  },
  {
    start: '10:30',
    end: '11:10',
    sessions: [
      { title: 'Deleting the cache layer and getting faster', track: 'Platform', speaker: 'Tobias Renner', room: 'Room A', href: '#' },
      { title: 'Type-safe forms without a runtime', track: 'Interface', speaker: 'Priya Ramanathan', room: 'Room B', href: '#' },
      { title: 'How we run a design review that people want to attend', track: 'Practice', speaker: 'Marcus Oyelaran', room: 'Room C', href: '#' },
    ],
  },
  {
    start: '11:20',
    end: '12:00',
    sessions: [
      { title: 'Postgres is still the answer, and here is the bill', track: 'Platform', speaker: 'Hana Lindqvist', room: 'Room A', href: '#' },
      { title: 'Animation that survives prefers-reduced-motion', track: 'Interface', speaker: 'Dev Kaur', room: 'Room B', href: '#' },
      { title: 'Estimating badly, on purpose', track: 'Practice', speaker: 'Ruth Okonjo', room: 'Room C', href: '#' },
    ],
  },
  {
    start: '12:00',
    end: '13:30',
    sessions: [{ title: 'Lunch, and the unconference board opens', kind: 'break' as const, room: 'Foyer' }],
  },
  {
    start: '13:30',
    end: '15:00',
    sessions: [
      { title: 'Workshop: profiling a slow page down to the frame', track: 'Platform', speaker: 'Tobias Renner', room: 'Lab 1', kind: 'workshop' as const, href: '#' },
      { title: 'Workshop: accessible components from first principles', track: 'Interface', speaker: 'Priya Ramanathan', room: 'Lab 2', kind: 'workshop' as const, href: '#' },
      { title: 'Open space: hiring without take-home tests', track: 'Practice', room: 'Room C', href: '#' },
    ],
  },
  {
    start: '15:20',
    end: '16:00',
    sessions: [
      { title: 'Five years of one monorepo, honestly assessed', track: 'Platform', speaker: 'Hana Lindqvist', room: 'Room A', href: '#' },
      { title: 'Design tokens after the second rename', track: 'Interface', speaker: 'Marcus Oyelaran', room: 'Room B', href: '#' },
      { title: 'What on-call does to a team, and what to do about it', track: 'Practice', speaker: 'Aisling Moreau', room: 'Room C', href: '#' },
    ],
  },
  {
    start: '16:15',
    end: '17:00',
    sessions: [
      { title: 'Closing panel: the parts we are all still doing by hand', room: 'Great Hall', kind: 'keynote' as const, href: '#' },
    ],
  },
  {
    start: '19:00',
    sessions: [{ title: 'Party at the Funkhaus — badge gets you in, no ticket needed', kind: 'break' as const, room: 'Funkhaus' }],
  },
]

const FRIDAY = [
  {
    start: '09:00',
    end: '09:30',
    sessions: [{ title: 'Coffee, and the unconference board is final at 09:30', kind: 'break' as const, room: 'Foyer' }],
  },
  {
    start: '09:30',
    end: '10:15',
    sessions: [
      {
        title: 'The incident that changed how we write postmortems',
        speaker: 'Ruth Okonjo',
        room: 'Great Hall',
        kind: 'keynote' as const,
        href: '#',
      },
    ],
  },
  {
    start: '10:30',
    end: '11:10',
    sessions: [
      { title: 'Queues, backpressure, and the outage we caused fixing one', track: 'Platform', speaker: 'Sam Oyelaran', room: 'Room A', href: '#' },
      { title: 'Server components, one year in production', track: 'Interface', speaker: 'Dev Kaur', room: 'Room B', href: '#' },
      { title: 'Documentation as a tier-one product', track: 'Practice', speaker: 'Elin Sørensen', room: 'Room C', href: '#' },
    ],
  },
  {
    start: '11:20',
    end: '12:00',
    sessions: [
      { title: 'Migrating 4TB without a maintenance window', track: 'Platform', speaker: 'Hana Lindqvist', room: 'Room A', href: '#' },
      { title: 'Testing a design system so it can be changed', track: 'Interface', speaker: 'Priya Ramanathan', room: 'Room B', href: '#' },
      { title: 'The unconference sessions, block one', track: 'Practice', room: 'Room C', href: '#' },
    ],
  },
  {
    start: '12:00',
    end: '13:30',
    sessions: [{ title: 'Lunch', kind: 'break' as const, room: 'Foyer' }],
  },
  {
    start: '13:30',
    end: '15:00',
    sessions: [
      { title: 'Workshop: reading a flame graph without guessing', track: 'Platform', speaker: 'Sam Oyelaran', room: 'Lab 1', kind: 'workshop' as const, href: '#' },
      { title: 'Workshop: writing a postmortem people read', track: 'Practice', speaker: 'Ruth Okonjo', room: 'Lab 2', kind: 'workshop' as const, href: '#' },
      { title: 'The unconference sessions, block two', track: 'Interface', room: 'Room B', href: '#' },
    ],
  },
  {
    start: '15:20',
    end: '16:00',
    sessions: [
      { title: 'What we would do differently, from four teams', room: 'Great Hall', kind: 'keynote' as const, href: '#' },
    ],
  },
  {
    start: '16:00',
    end: '16:30',
    sessions: [{ title: 'Close, and thank you', kind: 'break' as const, room: 'Great Hall' }],
  },
]

const HOW_TO_READ = [
  {
    question: 'What happens if two talks I want are at the same time?',
    answer:
      'Everything except the workshops is recorded and published free within two weeks, so a clash costs you the room and not the talk. The two keynotes and the closing panel deliberately run with nothing scheduled against them.',
  },
  {
    question: 'Do I need to sign up for the workshops in advance?',
    answer:
      'Yes — 24 seats each, booked from your order page, and they open two weeks before the event. A workshop ticket guarantees you a seat in one workshop per day, not in a specific one.',
  },
  {
    question: 'What is the unconference board?',
    answer:
      'A physical board in the foyer. Write a session and a room on it and it is on the programme; the Friday morning slots are filled this way. It opens at lunchtime on Thursday and is final at 09:30 on Friday.',
  },
  {
    question: 'Which rooms have live captions?',
    answer:
      'The Great Hall and Room A, both days, for every scheduled session. Room C is captioned on request with 24 hours’ notice — find any organiser or email us. Hearing loops are in all three rooms.',
  },
]

export default function SchedulePage() {
  return (
    <div className="min-h-screen bg-background text-foreground">
      <NavbarSimple
        brand="Frontier"
        links={[
          { label: 'Programme', href: '#sc-thursday' },
          { label: 'Speakers', href: '#' },
          { label: 'Tickets', href: '#' },
          { label: 'Venue', href: '#' },
        ]}
        activeLabel="Programme"
        ctaLabel="Book a ticket"
      />

      <main>
        <header className="mx-auto w-full max-w-6xl px-4 pt-12 sm:px-6 lg:px-8">
          <h1 className="text-3xl font-bold tracking-tight sm:text-4xl">The programme</h1>
          <p className="mt-3 max-w-2xl text-pretty text-muted-foreground">
            Both days in full. Eighteen talks, four workshops and an unconference track, across
            three rooms. Every scheduled session is recorded and published free within a
            fortnight — the workshops are not, deliberately.
          </p>
        </header>

        {/* The two headings differ on purpose: the block hashes its
            `aria-labelledby` target from heading + dayLabel, so identical
            strings would give both days the same id. */}
        <div id="sc-thursday">
          <EventAgendaGrid
            heading="Day one"
            dayLabel="Thursday 14 May"
            timeZoneLabel="All times CEST (Berlin)"
            slots={THURSDAY}
          />
        </div>

        <div id="sc-friday">
          <EventAgendaGrid
            heading="Day two"
            dayLabel="Friday 15 May"
            timeZoneLabel="All times CEST (Berlin)"
            slots={FRIDAY}
          />
        </div>

        <FaqAccordion
          heading="How to read this"
          subheading="Three tracks means a clash in almost every slot. Four questions about what that costs you."
          items={HOW_TO_READ}
        />
      </main>

      <FooterMinimal
        brand="Frontier"
        links={[
          { label: 'Programme', href: '#sc-thursday' },
          { label: 'Code of conduct', href: '#' },
          { label: 'Accessibility', href: '#' },
          { label: 'Past years', href: '#' },
        ]}
        socials={[{ label: 'GitHub', href: '#', icon: 'github' }]}
      />
    </div>
  )
}

menu-page.source:
/**
 * /menu — the whole bill of fare, and the page the site exists for.
 *
 *   food       three courses, typeset
 *   wine       a separate list, because it is priced by the glass and bottle
 *   answers    allergens, dietary requirements, the set lunch, corkage
 *   book       the table
 *
 * TWO <MenuCourseList>s RATHER THAN ONE WITH SIX COURSES. Food and drink
 * are read differently: a diner reads the food list once, top to bottom,
 * choosing three things; they read the wine list by price and by colour,
 * scanning a column. Splitting them lets the wine list carry its own
 * standfirst about corkage and its own two-price format ("9 / 34") without
 * that convention leaking into the food, where it would read as an error.
 *
 * The two lists also need distinct headings for a reason that is not
 * aesthetic — <MenuCourseList>'s section label is derived from its heading,
 * so two identically headed menus on one page would announce the second as
 * the first. Same class of duplicate-id problem the catalog hits every time
 * a block is used twice; here it is solved by the content being genuinely
 * different rather than by a prop.
 *
 * NO PHOTOGRAPHY ON THIS PAGE AND THAT IS A DECISION. A photograph of one
 * dish sets an expectation about plating that a kitchen changing its menu
 * weekly cannot meet, and a grid of twelve makes the page take four seconds
 * to load on the phone of someone standing outside deciding whether to come
 * in. The words are the product.
 *
 * <FaqCategorized> RATHER THAN <FaqAccordion>: the questions fall into three
 * genuinely separate groups — allergies, dietary requirements, and the
 * practical stuff about lunch and corkage — and a diner with a nut allergy
 * should not have to read about corkage to find their answer.
 *
 * Anchors are prefixed `mn-`.
 */

import * as React from 'react'
import { NavbarSimple } from '@/components/navbar-simple'
import { MenuCourseList } from '@/components/menu-course-list'
import { FaqCategorized } from '@/components/faq-categorized'
import { CtaSplitPanel } from '@/components/cta-split-panel'
import { FooterMinimal } from '@/components/footer-minimal'

const FOOD = [
  {
    name: 'To begin',
    note: 'Served until 3pm on Sundays',
    dishes: [
      {
        name: 'Devilled eggs, brown crab, lovage',
        description: 'Six halves. The crab is picked here on the morning it arrives.',
        price: '9',
        marks: ['gf', 's'],
      },
      {
        name: 'Bread and cultured butter',
        description: 'Sourdough from the Tuesday bake, salted butter churned in house.',
        price: '5',
        marks: ['v'],
      },
      {
        name: 'Chicory, pear, hazelnut, aged ewe’s cheese',
        description: 'Bitter, sweet, salt. The pears are from a single orchard in Herefordshire.',
        price: '11',
        marks: ['v', 'gf', 'n'],
      },
      {
        name: 'Potted shrimp on toast',
        description: 'Morecambe Bay brown shrimp, mace and cayenne, clarified butter.',
        price: '12',
        marks: ['s'],
      },
      {
        name: 'Leeks, burnt cream, sherry vinegar',
        description: 'Charred whole over embers, then dressed while still hot.',
        price: '10',
        marks: ['v', 'gf'],
      },
    ],
  },
  {
    name: 'Larger',
    note: 'All served with greens; potatoes are £5 and worth it',
    dishes: [
      {
        name: 'Hogget shoulder for two, anchovy and rosemary',
        description:
          'Four hours in the wood oven, carved at the table. Comes with greens and dripping potatoes.',
        price: '58',
        marks: ['gf'],
        signature: true,
      },
      {
        name: 'Whole plaice, brown butter, capers, sea beet',
        description: 'On the bone. Ask and we will take it off for you.',
        price: '28',
        marks: ['gf'],
      },
      {
        name: 'Barley, wild mushroom, pickled walnut, curd',
        description: 'The mushrooms change weekly; ask what came in.',
        price: '21',
        marks: ['v', 'n'],
      },
      {
        name: 'Dry-aged rib chop, bone marrow butter',
        description: 'Thirty-five days on the bone. Priced by weight on the day.',
        price: 'market price',
        marks: ['gf'],
      },
      {
        name: 'Salt-baked celeriac, hazelnut picada, sprouting broccoli',
        description: 'Ninety minutes in a salt crust, cracked open in the dining room.',
        price: '19',
        marks: ['ve', 'df', 'n'],
      },
    ],
  },
  {
    name: 'To finish',
    note: 'Cheese £4 a cut, £14 for four, from Bath Soft and Neal’s Yard',
    dishes: [
      {
        name: 'Burnt honey and thyme tart',
        description: 'Crème fraîche. The honey is from the roof of the building next door.',
        price: '10',
        marks: ['v'],
      },
      {
        name: 'Quince, brown sugar, oat cream',
        description: 'Poached slowly until it goes the colour of a penny.',
        price: '9',
        marks: ['ve', 'df'],
      },
      {
        name: 'Salted caramel and malt ice cream',
        description: 'One scoop, two scoops, or three if the table is sharing.',
        price: '5 / 8 / 10',
        marks: ['v', 'gf'],
      },
      {
        name: 'Chocolate, olive oil, sea salt',
        description: 'Made in the morning, set by service. When it is gone it is gone.',
        price: '9',
        marks: ['v', 'gf'],
      },
    ],
  },
]

const DRINK = [
  {
    name: 'By the glass',
    note: '125ml / 175ml / bottle',
    dishes: [
      {
        name: 'Bacchus, Dunleavy Vineyards, Somerset 2024',
        description: 'Elderflower and green apple. Grown eleven miles from this room.',
        price: '7 / 9 / 34',
        marks: ['ve'],
      },
      {
        name: 'Gamay, Domaine Dupré, Beaujolais 2023',
        description: 'Chilled, light, and the answer to most of the food on the left.',
        price: '8 / 11 / 42',
        marks: ['ve'],
      },
      {
        name: 'Nebbiolo, Produttori del Barbaresco 2020',
        description: 'For the hogget, or the rib chop, or both.',
        price: '12 / 16 / 62',
      },
      {
        name: 'Pét-nat, Offbeat Wines, Wiltshire 2024',
        description: 'Cloudy, dry, faintly of cider. The one the staff drink.',
        price: '9 / — / 44',
        marks: ['ve'],
      },
    ],
  },
  {
    name: 'Beer, cider and no alcohol',
    note: 'The alcohol-free list is a real list and not one token bottle',
    dishes: [
      { name: 'Lost & Grounded Keller Pils, Bristol', description: '330ml, 4.8%', price: '6' },
      { name: 'Wilding Cider, Somerset', description: '375ml bottle, 6.5%, bone dry', price: '9' },
      {
        name: 'Small Beer Session Pale, 2.1%',
        description: 'Brewed to be low, not de-alcoholised afterwards.',
        price: '5',
      },
      {
        name: 'Æcorn Aromatic, verjuice and gentian',
        description: 'Bitter, not sweet. Served with soda and a twist.',
        price: '7',
      },
      {
        name: 'Ballymaloe apple and elderflower soda',
        description: 'Made in house, no added sugar.',
        price: '4',
      },
    ],
  },
]

const QUESTIONS = [
  {
    name: 'Allergies',
    questions: [
      {
        question: 'Can you cook around a severe allergy?',
        answer:
          'Usually, and we would rather know when you book than when you sit down. We cook in one small kitchen with shared equipment, so we cannot promise any dish is free of a trace of anything — we will tell you honestly which dishes we are confident about and which we are not.',
      },
      {
        question: 'What do the letters after each dish mean?',
        answer:
          'They are at the foot of the menu: (v) vegetarian, (ve) vegan, (gf) gluten free, (df) dairy free, (n) contains nuts, (s) contains shellfish. They describe the dish as written — several can be changed, so ask.',
      },
      {
        question: 'Is the kitchen nut free?',
        answer:
          'No. We use hazelnuts and walnuts most weeks and they are stored and prepared in the same room. If that is a problem we will say so when you book rather than let you find out on the night.',
      },
    ],
  },
  {
    name: 'Dietary requirements',
    questions: [
      {
        question: 'Is there always a vegan option?',
        answer:
          'At every course, and it is a dish rather than a substitution — the salt-baked celeriac is the one the kitchen is proudest of this month. We do not do a separate vegan menu because it always ends up being the shorter one.',
      },
      {
        question: 'Can you do a gluten-free version of the bread?',
        answer:
          'No, and we would rather say so than serve a bad one. Most of the rest of the menu is gluten free as written; the marks on the menu are accurate.',
      },
    ],
  },
  {
    name: 'Practicalities',
    questions: [
      {
        question: 'Is there a set lunch?',
        answer:
          'Sundays only — two courses £26, three for £32, from noon until half past three. It is drawn from the same menu, not a cheaper one, and the hogget is on it most weeks.',
      },
      {
        question: 'Can I bring my own wine?',
        answer:
          'Wednesdays and Thursdays, £18 corkage a bottle, two bottles a table. Not on Friday or Saturday, when we need the table turn and the list to pay for itself.',
      },
      {
        question: 'Do you add a service charge?',
        answer:
          'A discretionary 12.5% on tables of six or more. It goes to the people who served you and is split evenly with the kitchen, which is not the industry norm. Ask us to remove it and we will, without a conversation about it.',
      },
      {
        question: 'How often does the menu change?',
        answer:
          'When the produce does, which in practice is most Wednesdays. This page is the menu — there is no printed one — so what you are reading now is what the kitchen is working from tonight.',
      },
    ],
  },
]

export default function MenuPage() {
  return (
    <div className="min-h-screen bg-background text-foreground">
      <NavbarSimple
        brand="Quay & Larder"
        links={[
          { label: 'Menu', href: '#mn-food' },
          { label: 'Wine', href: '#mn-drink' },
          { label: 'Find us', href: '#' },
        ]}
        activeLabel="Menu"
        ctaLabel="Book a table"
        ctaHref="#mn-book"
      />

      <main>
        <div id="mn-food">
          <MenuCourseList
            heading="Dinner"
            standfirst="Wednesday to Sunday, six until ten, kitchen closes at half past nine. One menu, changed when the produce changes rather than on a schedule — which is why there is no printed copy and this page is the only one."
            courses={FOOD}
          />
        </div>

        <div id="mn-drink">
          <MenuCourseList
            heading="To drink"
            standfirst="A short list, mostly from within a day’s drive, and priced so the second bottle is not a decision. Corkage is £18 on Wednesdays and Thursdays."
            courses={DRINK}
            footnote="Wines by the glass are poured to line from a measure at the pass, and we will always let you taste before the bottle is finished. The alcohol-free list is a proper list — we got tired of restaurants offering one sad bottle of grape juice."
          />
        </div>

        <FaqCategorized
          eyebrow="Before you order"
          heading="Allergies, diets and the practical things"
          topics={QUESTIONS}
        />

        <div id="mn-book">
          <CtaSplitPanel
            heading="Book a table"
            supporting="Thirty-eight covers and one sitting a night, so weekends go about ten days ahead. Wednesdays are usually free at short notice and are the better meal."
            primaryLabel="Check availability"
            secondaryLabel="Call 0117 946 2210"
            reassurance={[
              { text: 'Tell us about allergies when you book, not on the night' },
              { text: 'Cancel free up to 24 hours before' },
              { text: 'Corkage £18 on Wednesdays and Thursdays' },
            ]}
          />
        </div>
      </main>

      <FooterMinimal
        brand="Quay & Larder"
        links={[
          { label: 'Menu', href: '#mn-food' },
          { label: 'Wine', href: '#mn-drink' },
          { label: 'Book', href: '#mn-book' },
          { label: 'Gift vouchers', href: '#' },
        ]}
      />
    </div>
  )
}
